# Debug the single-valued detection
from collections import Counter

test_input = [
    [9, 9, 9, 9, 9, 9, 9, 8, 9],
    [9, 5, 2, 9, 1, 9, 9, 6, 1],
    [3, 9, 9, 9, 9, 9, 9, 6, 9],
    [9, 7, 9, 9, 7, 9, 9, 9, 8],
    [0, 0, 0, 0, 0, 0, 0, 0, 0],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9]
]

bg = 9
sep_val = 0

counts = Counter()
for row in test_input:
    for v in row:
        counts[v] += 1

print(f"All counts: {dict(counts)}")

single_vals = {}
for v, c in counts.items():
    if c == 1 and v not in [bg, sep_val]:
        print(f"Found single val: {v} appearing {c} time(s)")
        for r in range(len(test_input)):
            for c_idx in range(len(test_input[0])):
                if test_input[r][c_idx] == v:
                    single_vals[v] = (r, c_idx)
                    print(f"  Position: ({r}, {c_idx})")
                    break
            if v in single_vals:
                break

print(f"Single vals: {single_vals}")

# Apply propagation correctly
from collections import Counter

test_input = [
    [9, 9, 9, 9, 9, 9, 9, 8, 9],
    [9, 5, 2, 9, 1, 9, 9, 6, 1],
    [3, 9, 9, 9, 9, 9, 9, 6, 9],
    [9, 7, 9, 9, 7, 9, 9, 9, 8],
    [0, 0, 0, 0, 0, 0, 0, 0, 0],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9]
]

bg = 9
sep_val = 0

counts = Counter()
for row in test_input:
    for v in row:
        counts[v] += 1

single_vals = {}
for v, c in counts.items():
    if c == 1 and v not in [bg, sep_val]:
        for r in range(len(test_input)):
            for c_idx in range(len(test_input[0])):
                if test_input[r][c_idx] == v:
                    single_vals[v] = (r, c_idx)
                    break
            if v in single_vals:
                break

print(f"Single values: {single_vals}")

# Propagate each single value to rows r where r % 3 == (sr % 3)
result = [row[:] for row in test_input]
for val, (sr, sc) in single_vals.items():
    mod = sr % 3
    rows_to_propagate = [r for r in range(len(result)) if r % 3 == mod]
    for r in rows_to_propagate:
        result[r][sc] = val
        print(f"Setting ({r}, {sc}) = {val}")

print("\nOutput:")
print(json.dumps(result))

